// ... existing imports ...
import { Outlet, useNavigate, Link, Routes, Route } from 'react-router-dom'; // 👈 Add Routes, Route

// ... other imports ...
import Home from './Home';
import Students from './Students';
import Courses from './Courses';
import Questions from './Questions';
import CreateQuiz from './CreateQuiz';        // 👈 Add these
import AddQuestion from './AddQuestion';

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('');

  // Set active tab based on URL (optional but nice)
  useEffect(() => {
    const path = window.location.pathname;
    if (path.includes('/admin/students')) setActiveTab('students');
    else if (path.includes('/admin/courses')) setActiveTab('courses');
    else if (path.includes('/admin/questions')) setActiveTab('questions');
    else if (path.includes('/admin/quizzes/new')) setActiveTab('courses');
    else setActiveTab('dashboard');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  return (
    <div style={styles.container}>
      {/* Sidebar */}
      <div style={styles.sidebar}>
        <div style={styles.logo}>
          <img 
            src="https://cdn-icons-png.flaticon.com/512/2972/2972185.png" 
            alt="Quiz Logo" 
            style={styles.logoImg}
          />
        </div>
        <div className="navi">
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {[
              { id: 'dashboard', label: 'Home', icon: 'fa-home', path: '/admin' },
              { id: 'students', label: 'Students', icon: 'fa-user', path: '/admin/students' },
              { id: 'courses', label: 'Courses', icon: 'fa-book', path: '/admin/courses' },
              { id: 'questions', label: 'Questions', icon: 'fa-question', path: '/admin/questions' }
            ].map(item => (
              <li key={item.id}>
                <Link 
                  to={item.path}
                  onClick={() => setActiveTab(item.id)}
                  style={{
                    ...styles.navItem,
                    ...(activeTab === item.id ? styles.navItemActive : {})
                  }}
                >
                  <i className={`fa ${item.icon}`} style={styles.navIcon}></i>
                  <span>{item.label}</span>
                </Link>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Main Content */}
      <div style={styles.mainContent}>
        <header style={styles.header}>
          <div className="d-flex justify-content-between align-items-center">
            <h2>Admin Dashboard</h2>
            <button 
              onClick={handleLogout}
              className="btn btn-danger btn-sm"
            >
              Logout
            </button>
          </div>
        </header>

        {/* 👇 Nested Routes */}
        <Routes>
          <Route index element={<Home />} />
          <Route path="students" element={<Students />} />
          <Route path="courses" element={<Courses />} />
          <Route path="questions" element={<Questions />} />
          
          {/* 👇 ADD THESE TWO LINES HERE */}
          <Route path="quizzes/new" element={<CreateQuiz />} />
          <Route path="quizzes/:quizId/questions/new" element={<AddQuestion />} />
        </Routes>
      </div>
    </div>
  );
}
